import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]; BASE=ROOT/"problems"/"arrays"
tasks=[
 ("91-maximum-increasing-element-difference","Maximum Increasing Element Difference","Easy","Traversal","maximumDifference","int",["2 <= nums.length <= 100000","0 <= nums[i] <= 1000000000"],"O(n)","O(1)","Choose indices `i < j` with `nums[i] < nums[j]`. Return the largest possible difference `nums[j] - nums[i]`, or -1 if no such pair exists. Input: `nums`. Output: the maximum increasing difference or -1.","        low = nums[0]; best = -1\n        for x in nums[1:]:\n            if x > low: best = max(best, x - low)\n            low = min(low, x)\n        return best","        int low = nums[0], best = -1;\n        for (int i = 1; i < nums.length; i++) { if (nums[i] > low) best = Math.max(best, nums[i] - low); low = Math.min(low, nums[i]); }\n        return best;",[([7,1,5,4],4),([9,4,3,2],-1)],[[1,2],[2,1],[1,1,2],[1,5,2,10],[10,9,8,7],[3,3,4],[0,1000000000],[5,1,5,1,6],[8,2,6,1,9],[100,50,60,40,70]]),
 ("92-highest-altitude","Highest Altitude","Easy","Prefix/Suffix","largestAltitude","int",["1 <= gain.length <= 100000","-10000 <= gain[i] <= 10000"],"O(n)","O(1)","A cyclist starts at altitude 0. For each entry in `gain`, the altitude changes by that amount. Return the highest altitude reached, including the starting altitude. Input: the altitude changes `gain`. Output: the maximum altitude.","        altitude = best = 0\n        for x in gain: altitude += x; best = max(best, altitude)\n        return best","        int altitude = 0, best = 0;\n        for (int x : gain) { altitude += x; best = Math.max(best, altitude); }\n        return best;",[([-5,1,5,0,-7],1),([-4,-3,-2,-1,4,3,2],0)],[[1],[0,0],[5],[-1],[1,-1,1,-1],[3,3,3],[-3,-3,-3],[10,-20,15],[100,-50,-10],[0,1,-2,3]]),
 ("93-maximum-customer-wealth","Maximum Customer Wealth","Easy","Traversal","maximumWealth","long",["1 <= accounts.length, accounts[i].length <= 50","0 <= accounts[i][j] <= 1000000"],"O(m*n)","O(1)","A bank has customers whose account balances are listed by row in a matrix `accounts`. A customer's wealth is the sum of all balances in that row. Return the largest customer wealth. Input: rectangular matrix `accounts`. Output: the maximum row sum.","        return max(sum(row) for row in accounts)","        long best = 0;\n        for (int[] row : accounts) { long sum = 0; for (int x : row) sum += x; best = Math.max(best, sum); }\n        return best;",[([[1,2,3],[3,2,1]],6),([[1,5],[7,3],[3,5]],10)],[[[0]],[[5]],[[1,1,1]],[[0,0],[0,0]],[[10,0,0],[2,3,4]],[[1,2],[3,4],[5,6]],[[1000000,1000000],[1,1]],[[9,1,1],[5,5,1]],[[4,4,4,4]],[[2,3,4],[3,2,4]]]),
 ("94-count-pairs-with-absolute-difference-k","Count Pairs With Absolute Difference K","Easy","Traversal","countKDifference","long",["1 <= nums.length <= 100000","0 <= nums[i] <= 1000000000","0 <= k <= 1000000000"],"O(n)","O(n)","Count index pairs `i < j` such that `abs(nums[i] - nums[j]) == k`. Equal values at different indices form a valid pair when `k` is zero. Input: `nums`, `k`. Output: the pair count.","        counts = Counter(nums)\n        if k == 0: return sum(c * (c - 1) // 2 for c in counts.values())\n        return sum(c * counts.get(x + k, 0) for x, c in counts.items())","        Map<Integer, Long> counts = new HashMap<>(); for (int x : nums) counts.put(x, counts.getOrDefault(x,0L)+1);\n        long answer = 0;\n        if (k == 0) { for (long c : counts.values()) answer += c*(c-1)/2; }\n        else for (Map.Entry<Integer,Long> e : counts.entrySet()) answer += e.getValue()*counts.getOrDefault(e.getKey()+k,0L);\n        return answer;",[({"nums":[1,2,2,1],"k":1},4),({"nums":[1,3],"k":0},0)],[{"nums":[1,1],"k":0},{"nums":[1,1,1],"k":0},{"nums":[1,2,3],"k":1},{"nums":[1,2,3],"k":2},{"nums":[5,5,5,5],"k":1},{"nums":[0,1000000000],"k":1000000000},{"nums":[1,4,7,10],"k":3},{"nums":[2,2,3,3,4],"k":1},{"nums":[9],"k":0},{"nums":[1,2,1,2,1],"k":0}]),
 ("95-count-subarrays-with-maximum-value","Count Subarrays With Maximum Value","Medium","Subarrays","countSubarraysWithMaximum","long",["1 <= nums.length <= 100000","0 <= nums[i] <= 1000000000"],"O(n)","O(1)","Let `M` be the largest value anywhere in `nums`. Count non-empty contiguous subarrays whose bitwise AND equals `M`. Input: a non-negative integer array `nums`. Output: the number of such subarrays.","        maximum = max(nums)\n        run = answer = 0\n        for x in nums:\n            run = run + 1 if x == maximum else 0\n            answer += run\n        return answer","        int maximum = nums[0]; for (int x : nums) maximum = Math.max(maximum, x);\n        long answer = 0; int run = 0;\n        for (int x : nums) { run = x == maximum ? run + 1 : 0; answer += run; }\n        return answer;",[([1,3,3],6),([1,2,1],1)],[[1],[0,0],[5,5,5],[1,2,3],[4,4,2,4],[0,1,0,1],[7,6,7,7],[9,8,9,1],[1000000000,0,1000000000],[2,3,2,3]]),
 ("96-minimum-operations-to-make-sum-divisible","Minimum Operations to Make Sum Divisible","Easy","Traversal","minOperationsToDivisible","int",["1 <= nums.length <= 100000","0 <= nums[i] <= 1000000000","1 <= k <= 1000000000"],"O(n)","O(1)","In one operation, decrease any positive array element by 1. Find the minimum number of operations needed so the sum of `nums` is divisible by positive integer `k`. Input: non-negative array `nums` and `k`. Output: the minimum operations.","        return sum(nums) % k","        long sum = 0; for (int x : nums) sum += x;\n        return (int)(sum % k);",[({"nums":[3,9,7],"k":5},4),({"nums":[4,1,3],"k":4},0)],[{"nums":[0],"k":1},{"nums":[1],"k":2},{"nums":[5,5],"k":3},{"nums":[2,2,2],"k":4},{"nums":[10,20,30],"k":7},{"nums":[1,2,3],"k":6},{"nums":[0,0,0],"k":5},{"nums":[1000000000],"k":9},{"nums":[7,8,9,10],"k":3},{"nums":[4,4,4,4],"k":10}]),
 ("97-array-sum-versus-digit-sum","Array Sum Versus Digit Sum","Easy","Traversal","differenceOfSumAndDigitSum","int",["1 <= nums.length <= 1000","1 <= nums[i] <= 1000000"],"O(n*d)","O(1)","For each positive integer in `nums`, add its decimal digits to a digit sum. Return the absolute difference between the sum of the array elements and the total of all their digit sums. Input: `nums`. Output: the absolute difference.","        element_sum = sum(nums)\n        digit_sum = sum(sum(map(int, str(x))) for x in nums)\n        return abs(element_sum - digit_sum)","        int elementSum = 0, digitSum = 0;\n        for (int x : nums) { elementSum += x; int y = x; while (y > 0) { digitSum += y % 10; y /= 10; } }\n        return Math.abs(elementSum - digitSum);",[([1,15,6,3],9),([1,2,3,4],0)],[[1],[9],[10],[99],[123],[1,1,1],[100,200,300],[999,999],[12,34,56],[1000000,1]]),
 ("98-maximum-positive-or-negative-count","Maximum Positive or Negative Count","Easy","Traversal","maximumCount","int",["1 <= nums.length <= 100000","-100000 <= nums[i] <= 100000","nums is sorted in non-decreasing order"],"O(n)","O(1)","Given a non-decreasing sorted integer array `nums`, count its strictly negative elements and its strictly positive elements. Ignore zeros and return the larger of those two counts. Input: sorted `nums`. Output: the maximum count.","        negative = sum(x < 0 for x in nums)\n        positive = sum(x > 0 for x in nums)\n        return max(negative, positive)","        int negative = 0, positive = 0;\n        for (int x : nums) { if (x < 0) negative++; else if (x > 0) positive++; }\n        return Math.max(negative, positive);",[([-2,-1,-1,1,2,3],3),([-3,-2,-1,0,0,1,2],3)],[[0],[1],[ -1],[ -2,-1],[1,2],[0,0,0],[ -5,-2,0,0,1],[ -1,1],[ -5,-4,-3,-2,-1],[0,1,2,3,4]]),
 ("99-winner-of-array-game","Winner of an Array Game","Medium","Traversal","getWinner","int",["2 <= arr.length <= 100000","arr contains distinct positive integers","1 <= k <= 1000000000"],"O(n)","O(1)","An array game repeatedly compares the first two remaining values: the larger stays at the front and the smaller moves to the end. The first value to win `k` consecutive rounds is the winner. Return its value. Input: distinct-value array `arr` and positive `k`. Output: the winner.","        champion = arr[0]\n        wins = 0\n        for x in arr[1:]:\n            if champion > x: wins += 1\n            else: champion, wins = x, 1\n            if wins == k: return champion\n        return champion","        int champion = arr[0], wins = 0;\n        for (int i = 1; i < arr.length; i++) { if (champion > arr[i]) wins++; else { champion = arr[i]; wins = 1; } if (wins >= k) return champion; }\n        return champion;",[({"arr":[2,1,3,5,4,6,7],"k":2},5),({"arr":[3,2,1],"k":10},3)],[{"arr":[1,2],"k":1},{"arr":[2,1],"k":1},{"arr":[1,3,2],"k":2},{"arr":[3,1,2],"k":1},{"arr":[5,1,2,3,4],"k":3},{"arr":[1,2,3,4,5],"k":4},{"arr":[9,7,5,3,1],"k":2},{"arr":[2,5,1,4,3],"k":1000000},{"arr":[10,20,30,40],"k":2},{"arr":[7,1,6,2,5,3,4],"k":3}]),
 ("100-number-of-good-equal-value-pairs","Number of Good Equal-Value Pairs","Easy","Traversal","numberOfGoodPairs","int",["1 <= nums.length <= 1000","1 <= nums[i] <= 100"],"O(n)","O(n)","A good pair is a pair of indices `i < j` for which `nums[i] == nums[j]`. Given an integer array `nums`, count all good pairs. Input: `nums`. Output: the number of pairs.","        counts = Counter()\n        answer = 0\n        for x in nums:\n            answer += counts[x]\n            counts[x] += 1\n        return answer","        Map<Integer, Integer> counts = new HashMap<>(); int answer = 0;\n        for (int x : nums) { int seen = counts.getOrDefault(x,0); answer += seen; counts.put(x, seen+1); }\n        return answer;",[([1,2,3,1,1,3],4),([1,1,1,1],6)],[[1],[1,2],[1,1],[2,2,2],[1,2,1,2],[1,2,3,4],[5,5,5,5,5],[1,1,2,2],[100,100,1],[3,2,1,3,2,1]]),
]

for i, task in enumerate(tasks):
    row=list(task)
    if row[0]=="95-count-subarrays-with-maximum-value": row[12]=[([1,3,3],3),([1,2,1],1)]
    tasks[i]=tuple(row)
roster_path=ROOT/"problems"/"roster.json"; roster=json.loads(roster_path.read_text())
for slug,title,diff,subtopic,method,ret,constraints,time,space,desc,py,java,examples,tests in tasks:
    folder=BASE/slug; folder.mkdir()
    params=[{"name":"nums","type":"int[]"}]
    if slug=="92-highest-altitude": params=[{"name":"gain","type":"int[]"}]
    if slug=="93-maximum-customer-wealth": params=[{"name":"accounts","type":"int[][]"}]
    if slug in ("94-count-pairs-with-absolute-difference-k","96-minimum-operations-to-make-sum-divisible","99-winner-of-array-game"): params=[{"name":"arr" if slug.startswith("99-") else "nums","type":"int[]"},{"name":"k","type":"int"}]
    if slug=="99-winner-of-array-game": params=[{"name":"arr","type":"int[]"},{"name":"k","type":"int"}]
    if slug=="95-count-subarrays-with-maximum-value": params=[{"name":"nums","type":"int[]"}]
    if slug=="94-count-pairs-with-absolute-difference-k": params=[{"name":"nums","type":"int[]"},{"name":"k","type":"int"}]
    cases=[x for x,_ in examples]+tests
    def fmt(x): return ", ".join(f"{name} = {json.dumps(v)}" for name,v in x.items()) if isinstance(x,dict) else f"{params[0]['name']} = {json.dumps(x)}"
    def outfmt(y): return json.dumps(y,separators=(",",":")) if isinstance(y,list) else str(y)
    jtype={"int":"int","long":"long"}[ret]
    meta={"title":title,"difficulty":diff,"subtopic":subtopic,"companies":["Amazon","Google","Microsoft"],"description":desc,"constraints":constraints,"hints":["Keep a running total or frequency count rather than recomputing over all prefixes.","Test repeated values, zeros, and minimum-size inputs."],"examples":[{"input":fmt(x),"output":outfmt(y)} for x,y in examples],"timeComplexity":time,"spaceComplexity":space,"compare":"exact","signature":{"kind":"function","method":method,"params":params,"returns":ret}}
    (folder/"problem.json").write_text(json.dumps(meta,indent=2)+"\n")
    ptype=lambda t: "List[List[int]]" if t=="int[][]" else "List[int]" if t=="int[]" else "int"
    pyparams="".join(f", {p['name']}: {ptype(p['type'])}" for p in params)
    (folder/"solution.py").write_text(f"class Solution:\n    def {method}(self{pyparams}) -> int:\n"+py+"\n")
    jtypeparam={"int[]":"int[]","int[][]":"int[][]","int":"int"}
    jparams=", ".join(f"{jtypeparam[p['type']]} {p['name']}" for p in params)
    (folder/"Solution.java").write_text(f"class Solution {{\n    public {jtype} {method}({jparams}) {{\n"+java+"\n    }\n}\n")
    conv=lambda x:x if isinstance(x,dict) else {params[0]["name"]:x}
    (folder/"tests.py").write_text("def visible():\n    return "+repr([{"in":conv(x)} for x in cases[:3]])+"\n\ndef hidden():\n    return "+repr([{"in":conv(x)} for x in cases[3:]])+"\n")
    roster.setdefault("arrays",[]).append([slug,title,diff,subtopic,None])
roster_path.write_text(json.dumps(roster,indent=2)+"\n")
print(f"Created {len(tasks)} array questions")
